<script setup lang="ts">
import type { Settings } from '../../game/services/storage';
import DialogFrame from './DialogFrame.vue';
const props = defineProps<{ settings: Settings }>(); const emit = defineEmits<{ change: [settings: Settings]; close: [] }>();
function volume(event: Event) { if (event.target instanceof HTMLInputElement) emit('change', { ...props.settings, volume: Number(event.target.value) }); }
function visuals(event: Event) { if (event.target instanceof HTMLInputElement) emit('change', { ...props.settings, effectsIntensity: Number(event.target.value) }); }
</script>
<template><DialogFrame label="Настройки" @close="emit('close')"><small>ПОД СВОЙ РИТМ</small><h1>Настройки</h1><label class="setting">Громкость <span>{{ Math.round(settings.volume * 100) }}%</span><input aria-label="Громкость" type="range" min="0" max="1" step="0.05" :value="settings.volume" @input="volume"></label><label class="setting inline"><span>Выключить звук</span><input type="checkbox" :checked="settings.muted" @change="emit('change', { ...settings, muted: !settings.muted })"></label><div class="setting inline"><span>Масштаб пикселей</span><div><button class="small-button" :aria-pressed="settings.pixelScale === 2" @click="emit('change', { ...settings, pixelScale: 2 })">2×</button> <button class="small-button" :aria-pressed="settings.pixelScale === 3" @click="emit('change', { ...settings, pixelScale: 3 })">3×</button></div></div><label class="setting">Интенсивность эффектов<input aria-label="Интенсивность эффектов" type="range" min="0" max="1" step="0.1" :value="settings.effectsIntensity ?? 0.7" @input="visuals"></label><label class="setting inline"><span>Цифры урона</span><input type="checkbox" :checked="settings.damageNumbers ?? false" @change="emit('change', { ...settings, damageNumbers: !settings.damageNumbers })"></label><p class="muted">Сохраняется только в этом браузере.</p><button @click="emit('close')">Готово</button></DialogFrame></template>
